import{Rt as e,dt as t,mt as n,n as r}from"./chunks/framework.BkIgthgQ.js";var i=JSON.parse(`{"title":"Operations","description":"GET /api/v1/health vs ready. GET /api/v1/ready is 404. Runtime DB. Redis fallback.","frontmatter":{"title":"Operations","description":"GET /api/v1/health vs ready. GET /api/v1/ready is 404. Runtime DB. Redis fallback."},"headers":[],"relativePath":"en/faq/ops.md","filePath":"en/faq/ops.md","lastUpdated":1790057721000}`),a={name:`en/faq/ops.md`};function o(r,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[n(`<h1 id="operations" tabindex="-1">Operations <a class="header-anchor" href="#operations" aria-label="Permalink to “Operations”">​</a></h1><ul><li><code>GET /api/v1/health</code>: always 200. <code>ready</code> = DB + storage, <strong>not Redis</strong>.</li><li><code>GET /api/v1/ready</code>: <strong>404</strong>. Not a readiness probe.</li><li>Runtime Postgres outage: business <code>/api</code> is 404; health stays 200 with <code>ready=false</code>.</li><li>Redis: startup Ping is required when <code>driver=redis</code>; a later outage falls back to memory and reconnects.</li><li>Reverse proxies must set per-plane <code>trusted_proxies</code>; an empty list does not trust all <code>X-Forwarded-For</code>.</li><li>Backups: <a href="/en/guide/backup">Backup</a>. There is no <code>kirivers listen</code>. No separate migrate CLI (AutoMigrate).</li></ul>`,2)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};